save_config() {
    load_config
    cat > "$CONFIG_FILE" <<EOF
{
  "threshold": $THRESHOLD,
  "depth": "$DEPTH",
  "quiet_hours": "$QUIET_HOURS",
  "last_compression": "$(date -Iseconds 2>/dev/null || echo "")",
  "total_compressions": $((TOTAL_COMPRESSIONS + 1))
}
EOF
}

# Get all sessions as JSON
get_all_sessions() {
    openclaw sessions --json 2>/dev/null
}

